```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

struct Node;

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        let mut message = String::new();
        message.push_str("Digest ");
        message.push_str(&composed.date);
        message.push('\n');
        message.push_str(&composed.overview);
        message.push('\n');

        for entry in composed.entries.iter().filter(|e| e.kept) {
            message.push_str("- ");
            message.push_str(&entry.title);
            message.push_str(" <");
            message.push_str(&entry.link);
            message.push_str(">\n");
        }

        let published = aap::caps::notifier::notify(&message);

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
